#!/usr/bin/env node
/**
 * Codegen: snapshot the canonical skill files into a Worker module so the
 * `/api/me/skill` download can zip them on the fly (the Worker has no
 * filesystem at runtime). Run before `wrangler dev` / `wrangler deploy` —
 * wired into the package.json `dev` and `predeploy` scripts — so the served
 * bundle never drifts from the real skill on disk.
 *
 * The `.env` is NOT bundled here; the Worker bakes a per-user `.env` at
 * download time (API_BASE / API_KEY / USER_EMAIL).
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SKILL = join(ROOT, 'skill');
const OUT = join(ROOT, 'worker', 'generated', 'skill-bundle.ts');

// Paths are relative to the skill root → they become the zip entry names.
const FILES = ['SKILL.md', 'scripts/stash.py'];

const bundle = {};
for (const rel of FILES) {
  bundle[rel] = readFileSync(join(SKILL, rel), 'utf8');
}

const banner =
  '// AUTO-GENERATED by scripts/gen-bundle.mjs — do not edit by hand.\n' +
  '// Source of truth: skill/. Regenerated on dev/deploy.\n';

const body =
  banner +
  'export const SKILL_BUNDLE: Record<string, string> = ' +
  JSON.stringify(bundle, null, 2) +
  ';\n';

mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(OUT, body, 'utf8');
console.log(`gen-bundle: wrote ${OUT} (${FILES.length} files)`);
